const KEY='slow-steady-recipes-v1';
const seed=[
 {id:'cap',name:'Cappuccino',category:'นม',serve:'ร้อน',size:'6 oz',price:70,cost:25,dose:18,yield:36,shotTime:28,notes:'ไมโครโฟมเนียน อุณหภูมินมไม่เกิน 65°C',ingredients:[{name:'เมล็ดกาแฟ',amount:'18 g'},{name:'นมสด',amount:'120 ml'}],steps:[{text:'สกัด Espresso 18 g ให้ได้น้ำกาแฟ 36 g',time:28},{text:'สตรีมนมให้เป็นไมโครโฟมเนียน',time:35},{text:'เทนมผสมกับช็อตและเสิร์ฟ',time:0}]},
 {id:'latte',name:'Iced Latte',category:'Signature',serve:'เย็น',size:'16 oz',price:75,cost:28,dose:18,yield:38,shotTime:28,notes:'สูตรขายดีของร้าน',ingredients:[{name:'เมล็ดกาแฟ',amount:'18 g'},{name:'นมสด',amount:'135 ml'},{name:'น้ำแข็ง',amount:'160 g'}],steps:[{text:'ใส่นมและน้ำแข็งลงแก้ว',time:0},{text:'สกัด Espresso ให้ได้ 38 g',time:28},{text:'เทช็อตด้านบนและเสิร์ฟ',time:0}]},
 {id:'ame',name:'Americano เย็น',category:'Espresso',serve:'เย็น',size:'16 oz',price:65,cost:18,dose:18,yield:36,shotTime:27,notes:'รสสะอาด หอมชัด',ingredients:[{name:'เมล็ดกาแฟ',amount:'18 g'},{name:'น้ำ',amount:'120 ml'},{name:'น้ำแข็ง',amount:'170 g'}],steps:[{text:'เติมน้ำและน้ำแข็งลงแก้ว',time:0},{text:'สกัด Espresso 36 g',time:27},{text:'เทช็อตลงด้านบน',time:0}]},
 {id:'v60',name:'V60 House Blend',category:'Slow Bar',serve:'ร้อน',size:'240 ml',price:90,cost:32,dose:15,yield:240,shotTime:150,notes:'บดกลาง น้ำ 92°C',ingredients:[{name:'เมล็ดกาแฟ',amount:'15 g'},{name:'น้ำร้อน 92°C',amount:'240 g'}],steps:[{text:'Bloom ด้วยน้ำ 40 g',time:30},{text:'เทน้ำรอบสองถึง 140 g',time:40},{text:'เทรอบสุดท้ายถึง 240 g',time:80}]}
];
let recipes=load(),category='ทั้งหมด',current=null,brew={recipe:null,index:0,remaining:0,timer:null};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function load(){try{return JSON.parse(localStorage.getItem(KEY))||seed}catch{return seed}}
function save(){localStorage.setItem(KEY,JSON.stringify(recipes))}
function money(n){return new Intl.NumberFormat('th-TH',{maximumFractionDigits:2}).format(Number(n)||0)}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function icon(cat){return cat==='Slow Bar'?'▽':cat==='นม'?'◌':cat==='Signature'?'✦':'☕'}
function render(){renderChips();const q=$('#searchInput').value.trim().toLowerCase();const list=recipes.filter(r=>(category==='ทั้งหมด'||r.category===category)&&(`${r.name} ${r.category} ${r.ingredients.map(i=>i.name).join(' ')}`.toLowerCase().includes(q)));$('#recipeCount').textContent=`${list.length} เมนู`;$('#recipeList').innerHTML=list.length?list.map(r=>`<button class="recipe-card" data-id="${r.id}"><span class="recipe-icon">${icon(r.category)}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.serve)} · ${esc(r.size)} · ${r.dose||0}→${r.yield||0} g</small></span><span class="arrow">›</span></button>`).join(''):'<div class="empty">ยังไม่พบสูตร ลองเปลี่ยนคำค้นหาหรือเพิ่มสูตรใหม่</div>';const f=recipes.find(r=>r.category==='Signature')||recipes[0];$('#featuredRecipe').innerHTML=f?`<div><small>SIGNATURE RECIPE</small><h2>${esc(f.name)}</h2><p>${esc(f.size)} · ${money(f.price)} บาท</p></div><button data-brew="${f.id}">เริ่มชง</button>`:'<div><h2>เริ่มสร้างสูตรแรก</h2></div>';renderCosts()}
function renderChips(){const cats=['ทั้งหมด',...new Set(recipes.map(r=>r.category))];$('#categoryChips').innerHTML=cats.map(c=>`<button class="${c===category?'active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}
function renderCosts(){const margins=recipes.filter(r=>r.price>0).map(r=>(r.price-r.cost)/r.price*100);$('#avgMargin').textContent=`${margins.length?Math.round(margins.reduce((a,b)=>a+b,0)/margins.length):0}%`;$('#costList').innerHTML=recipes.map(r=>`<div class="cost-row"><div><strong>${esc(r.name)}</strong><small>ขาย ${money(r.price)} บาท · ต้นทุน ${money(r.cost)} บาท</small></div><div><strong>${money(r.price-r.cost)} ฿</strong><em>กำไร ${r.price?Math.round((r.price-r.cost)/r.price*100):0}%</em></div></div>`).join('')}
function showDetail(id){current=recipes.find(r=>r.id===id);if(!current)return;$('#detailContent').innerHTML=`<div class="detail-head"><button class="round-button" data-close-detail>×</button><button class="text-button accent" data-edit="${current.id}">แก้ไข</button></div><div class="detail-hero"><div class="detail-icon">${icon(current.category)}</div><h2>${esc(current.name)}</h2><p>${esc(current.serve)} · ${esc(current.size)} · สูตรร้านเรา</p></div><div class="detail-body"><div class="spec-grid"><div class="spec"><small>Espresso</small><strong>${current.dose||0} → ${current.yield||0} g</strong></div><div class="spec"><small>เวลา</small><strong>${current.shotTime||0} วินาที</strong></div><div class="spec"><small>ราคาขาย</small><strong>${money(current.price)} บาท</strong></div><div class="spec"><small>ต้นทุน</small><strong>${money(current.cost)} บาท</strong></div></div><h3>วัตถุดิบ</h3><ul class="ingredients">${current.ingredients.map(i=>`<li><span>${esc(i.name)}</span><strong>${esc(i.amount)}</strong></li>`).join('')}</ul><h3>ขั้นตอนการทำ</h3><ol class="steps">${current.steps.map((s,i)=>`<li><span class="step-number">${i+1}</span><span>${esc(s.text)}${s.time?`<small> · ${s.time} วินาที</small>`:''}</span></li>`).join('')}</ol>${current.notes?`<h3>หมายเหตุ</h3><p>${esc(current.notes)}</p>`:''}</div><div class="detail-actions"><button class="secondary-button" data-edit="${current.id}">แก้ไข</button><button class="primary-button" data-brew="${current.id}">เริ่มทำตามสูตร</button></div>`;$('#detailDialog').showModal()}
function rowIngredient(v={name:'',amount:''}){const d=document.createElement('div');d.className='ingredient-row';d.innerHTML=`<input class="ing-name" placeholder="วัตถุดิบ" value="${esc(v.name)}"><input class="ing-amount" placeholder="ปริมาณ" value="${esc(v.amount)}"><button type="button" class="remove-row">×</button>`;return d}
function rowStep(v={text:'',time:0}){const d=document.createElement('div');d.className='step-row';d.innerHTML=`<input class="step-text" placeholder="อธิบายขั้นตอน" value="${esc(v.text)}"><input class="step-time" type="number" min="0" placeholder="วินาที" value="${v.time||''}"><button type="button" class="remove-row">×</button>`;return d}
function openForm(id){const r=id?recipes.find(x=>x.id===id):null;current=r;$('#formTitle').textContent=r?'แก้ไขสูตร':'เพิ่มสูตรใหม่';$('#recipeId').value=r?.id||'';for(const k of ['name','category','serve','size','price','dose','yield','shotTime','cost','notes'])$('#'+k).value=r?.[k]??'';$('#ingredientRows').innerHTML='';(r?.ingredients?.length?r.ingredients:[{}]).forEach(v=>$('#ingredientRows').append(rowIngredient(v)));$('#stepRows').innerHTML='';(r?.steps?.length?r.steps:[{}]).forEach(v=>$('#stepRows').append(rowStep(v)));$('#deleteRecipe').hidden=!r;$('#recipeDialog').showModal()}
function submitForm(){const id=$('#recipeId').value||crypto.randomUUID();const data={id};for(const k of ['name','category','serve','size','notes'])data[k]=$('#'+k).value.trim();for(const k of ['price','dose','yield','shotTime','cost'])data[k]=Number($('#'+k).value)||0;data.ingredients=$$('#ingredientRows .ingredient-row').map(x=>({name:x.querySelector('.ing-name').value.trim(),amount:x.querySelector('.ing-amount').value.trim()})).filter(x=>x.name);data.steps=$$('#stepRows .step-row').map(x=>({text:x.querySelector('.step-text').value.trim(),time:Number(x.querySelector('.step-time').value)||0})).filter(x=>x.text);const i=recipes.findIndex(x=>x.id===id);if(i>=0)recipes[i]=data;else recipes.unshift(data);save();render();toast(i>=0?'แก้ไขสูตรแล้ว':'เพิ่มสูตรแล้ว')}
function startBrew(id){const r=recipes.find(x=>x.id===id);if(!r||!r.steps.length)return toast('สูตรนี้ยังไม่มีขั้นตอน');$('#detailDialog').close();brew.recipe=r;brew.index=0;renderBrew();$('#brewDialog').showModal()}
function renderBrew(){clearInterval(brew.timer);const s=brew.recipe.steps[brew.index];brew.remaining=s.time||0;$('#brewContent').innerHTML=`<div class="brew-head"><button data-close-brew>×</button><strong>${esc(brew.recipe.name)}</strong><span>${brew.index+1}/${brew.recipe.steps.length}</span></div><div class="progress"><span style="width:${(brew.index+1)/brew.recipe.steps.length*100}%"></span></div><div class="brew-main"><p class="eyebrow">ขั้นตอนที่ ${brew.index+1}</p><div class="brew-symbol">${icon(brew.recipe.category)}</div><h2>${esc(s.text)}</h2><p>${s.time?'กดเริ่มจับเวลาเมื่อพร้อม':'ทำขั้นตอนนี้ให้เรียบร้อย แล้วกดถัดไป'}</p>${s.time?`<div class="timer" id="timer">${formatTime(s.time)}</div><button class="timer-button" data-start-timer>▷ เริ่มจับเวลา</button>`:''}</div><div class="brew-actions"><button data-prev ${brew.index===0?'disabled':''}>ย้อนกลับ</button><button data-next>${brew.index===brew.recipe.steps.length-1?'ชงเสร็จแล้ว':'ขั้นตอนถัดไป'}</button></div>`}
function formatTime(n){return`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function startTimer(){const b=$('[data-start-timer]');b.disabled=true;b.textContent='กำลังจับเวลา';brew.timer=setInterval(()=>{brew.remaining--;$('#timer').textContent=formatTime(Math.max(0,brew.remaining));if(brew.remaining<=0){clearInterval(brew.timer);b.textContent='✓ ครบเวลาแล้ว';toast('ครบเวลาแล้ว')}},1000)}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.id==='addRecipeTop')openForm();if(t.dataset.id)showDetail(t.dataset.id);if(t.dataset.cat){category=t.dataset.cat;render()}if(t.dataset.page){$$('.page').forEach(x=>x.classList.toggle('active',x.id===t.dataset.page));$$('.nav-item').forEach(x=>x.classList.toggle('active',x===t))}if(t.dataset.close!==undefined)$('#recipeDialog').close();if(t.dataset.closeDetail!==undefined)$('#detailDialog').close();if(t.dataset.edit){$('#detailDialog').close();openForm(t.dataset.edit)}if(t.dataset.brew)startBrew(t.dataset.brew);if(t.dataset.action==='quick-brew')startBrew(recipes[0]?.id);if(t.id==='addIngredient')$('#ingredientRows').append(rowIngredient());if(t.id==='addStep')$('#stepRows').append(rowStep());if(t.classList.contains('remove-row'))t.parentElement.remove();if(t.id==='deleteRecipe'&&current){recipes=recipes.filter(r=>r.id!==current.id);save();render();$('#recipeDialog').close();toast('ลบสูตรแล้ว')}if(t.dataset.closeBrew!==undefined){clearInterval(brew.timer);$('#brewDialog').close()}if(t.dataset.startTimer!==undefined)startTimer();if(t.dataset.prev!==undefined&&brew.index>0){brew.index--;renderBrew()}if(t.dataset.next!==undefined){if(brew.index<brew.recipe.steps.length-1){brew.index++;renderBrew()}else{clearInterval(brew.timer);$('#brewDialog').close();toast('ชงเสร็จแล้ว พร้อมเสิร์ฟ')}}});
$('#recipeForm').addEventListener('submit',e=>{e.preventDefault();if(!$('#name').value.trim())return;submitForm();$('#recipeDialog').close()});
$('#searchInput').addEventListener('input',render);render();
